"use strict";

var ENGINE = ENGINE || {};
ENGINE.SimulatorCommon = {
  init: function init() {
    // ホバー時にクラス付与
    $('.js_hover').hover(function () {
      $('body').addClass('is_hover');
    }, function () {
      $('body').removeClass('is_hover');
    });
  },

  /**
   * CSVファイルの解析
   *
   */
  parseCSV: function parseCSV(csv) {
    var tmp = [];
    csv = csv.replace(/("[^"]*")+/g, function (match) {
      tmp.push(match.slice(1, -1).replace(/""/g, '"'));
      return '[TMP]';
    });
    return csv.split("\n").map(function (row) {
      return row.split(',').map(function (val) {
        return val === '[TMP]' ? tmp.shift() : val.trim();
      });
    });
  },

  /**
   * CSV形式のデータをJSON形式に変換
   * ※製品マスタで定義されたCSVファイル
   *
   */
  parseCSV2JSON: function parseCSV2JSON(data) {
    var products = []; // タイトル行の取得

    var title;
    var titles = data[2]; // 3行目からデータ行

    for (var row_idx = 3, row_max = data.length; row_idx < row_max; row_idx++) {
      var product = {};

      for (var col_idx = 0, col_max = data[row_idx].length; col_idx < col_max; col_idx++) {
        title = (titles[col_idx] + '').trim();
        product[title] = (data[row_idx][col_idx] + '').trim();
      }

      products.push(product);
    }

    return products;
  },

  /**
   * ファイル読み込み
   *
   */
  load: function load(url, callback_func, error_func, progress_func) {
    var _this = this;

    var xhr = new XMLHttpRequest();
    progress_func = progress_func && typeof progress_func == 'function' ? progress_func : console.log; // Handlerの登録.

    xhr.onreadystatechange = function () {
      switch (xhr.readyState) {
        case 0:
          // 未初期化状態.
          progress_func(xhr.readyState);
          break;

        case 1:
          // データ送信中.
          progress_func(xhr.readyState);
          break;

        case 2:
          // 応答待ち.
          progress_func(xhr.readyState);
          break;

        case 3:
          // データ受信中.
          progress_func(xhr.readyState, xhr.responseText.length);
          break;

        case 4:
          // データ受信完了.
          if (xhr.status == 200 || xhr.status == 304) {
            var data = xhr.responseText; // responseXML もあり

            progress_func(xhr.readyState);
            callback_func(data);
          } else {
            progress_func(xhr.readyState);
            error_func(xhr.statusText);
          }

          break;
      }
    };

    xhr.open("get", url, false);
    xhr.send(null);
    xhr.abort(); // 再利用する際にも abort() しないと再利用できない
  },

  /**
   * 金額表示フォーマット変更
   *
   */
  priceFormat: function priceFormat(num, options) {
    var cnv = num + ''; // 不要な文字を削除

    cnv = cnv.replace(/[^0-9\.]/g, ''); // 数値形式に変換

    cnv = Number(cnv); // 小数点表示ありの場合

    var digit = options && options['price_decimal_point_digit'] ? options['price_decimal_point_digit'] : 0;
    cnv = cnv.toFixed(digit); // 3桁区切り文字の取得

    var token = options && options['price_token'] ? options['price_token'] : ','; // 金額のフォーマット変換

    var price = String(cnv).replace(/(\d)(?=(\d\d\d)+(?!\d))/g, '$1' + token); // 金額単位の取得

    var price_unit = options && options['price_unit'] ? options['price_unit'] : ''; // 金額単位の表示位置の取得

    var price_unit_pos = options && options['price_unit_pos'] ? options['price_unit_pos'] : 0; // 単位の設定

    if (price_unit) {
      if (price_unit_pos == 2) {
        price = price + ' ' + price_unit;
      } else {
        price = price_unit + ' ' + price;
      }
    }

    return price;
  },

  /**
   *
   *
   */
  zeroPadding: function zeroPadding(num, len) {
    return ('0000000000' + num).slice(-len);
  },

  /**
   * ファイル読み込み
   *
   */
  stageFit: function stageFit() {
    var $win = $(window);
    var $stage = $('.js-stage');

    var _STAGE_H = $stage.height();

    var _STAGE_W = $stage.width();

    var _RATIO = _STAGE_W / _STAGE_H; // $win.off('resize', )


    $win.off('resize.stagefit');
    $win.on('resize.stagefit', _init);

    function _init() {
      $stage.each(function () {
        _fit($(this));
      });
    }

    function _fit($target) {
      // console.log('resize');
      // console.log('resize : ' + $stage.length);
      _STAGE_H = $target.height();
      _STAGE_W = $target.width();

      if (_STAGE_H == 0 || _STAGE_W == 0) {
        return;
      }

      _RATIO = _STAGE_W / _STAGE_H; // console.log(_STAGE_H + ' : ' + _STAGE_W + ' => ' + _RATIO);

      if (_RATIO > 0 && _RATIO < 0.5) {
        $target.addClass('is-tatenaga-s');
        $target.removeClass('is-tatenaga');
        $target.removeClass('is-yokonaga');
        $target.removeClass('is-yokonaga-s');
      } else if (_RATIO > 0 && _RATIO < 1) {
        $target.removeClass('is-tatenaga-s');
        $target.addClass('is-tatenaga');
        $target.removeClass('is-yokonaga');
        $target.removeClass('is-yokonaga-s');
      } else if (_RATIO > 1.75) {
        $target.removeClass('is-tatenaga-s');
        $target.removeClass('is-tatenaga');
        $target.removeClass('is-yokonaga');
        $target.addClass('is-yokonaga-s');
      } else if (_RATIO > 2.5) {
        $target.removeClass('is-tatenaga-s');
        $target.removeClass('is-tatenaga');
        $target.removeClass('is-yokonaga-s');
        $target.addClass('is-yokonaga');
      } else {
        $target.removeClass('is-tatenaga-s');
        $target.removeClass('is-tatenaga');
        $target.removeClass('is-yokonaga');
        $target.removeClass('is-yokonaga-s');
      }
    }

    _init();
  },

  /**
   *
   *
   */
  getUniqueID: function getUniqueID() {
    var strong = 10000000000000000;
    return new Date().getTime().toString() + Math.floor(strong * Math.random()).toString() + '-';
  },

  /**
   *
   *
   */
  getURLParameter: function getURLParameter() {
    var qstr = window.location.href;
    var regex = /[?&]([^=#]+)=([^&#]*)/g;
    var result = {};
    var match;

    while (match = regex.exec(qstr)) {
      result[match[1]] = match[2];
    }

    return result;
  },

  /**
   *
   *
   */
  array_key_exists: function array_key_exists(key, search) {
    // http://kevin.vanzonneveld.net
    // +   original by: Kevin van Zonneveld (http://kevin.vanzonneveld.net)
    // +   improved by: Felix Geisendoerfer (http://www.debuggable.com/felix)
    // *     example 1: array_key_exists('kevin', {'kevin': 'van Zonneveld'});
    // *     returns 1: true
    // input sanitation
    if (!search || search.constructor !== Array && search.constructor !== Object) {
      return false;
    }

    return key in search;
  },

  /**
   *
   *
   */
  nl2br: function nl2br(str) {
    var result = str;
    result = result.replace(/\r\n/g, '<br>');
    result = result.replace(/(\n|\r)/g, '<br>');
    return result;
  }
};
