  downloadPDF4Saved: function downloadPDF4Saved(type, favarite_id) {
    // ENGINE.log('downloadPDF4Saved() - start.');
    var favorite = ENGINE.Simulator.getFavorite(favarite_id); // ENGINE.log(favarite_id);
    // ENGINE.log(favorite);

    var params = {
      'over-head-shower': favorite['oid'],
      'hand-shower': favorite['hid'],
      'bath-spout': favorite['bid'],
      'controller': favorite['cid'],
      'valve1': favorite['v1id'],
      'valve2': favorite['v2id'],
      'accessory1': favorite['a1id'],
      'accessory2': favorite['a2id'],
      'accessory3': favorite['a3id'],
      'controller-relation-no': favorite['pos']
    };
    var qstr = ENGINE.Simulator.generateURLParameter(params);
    var download_url = ENGINE.Simulator.settings['api_url'] && ENGINE.Simulator.settings['api_url']['shower']['download'] ? ENGINE.Simulator.settings['api_url']['shower']['download'] : '';

    if (download_url) {
      download_url = download_url + qstr; // ENGINE.log(download_url);

      window.open(download_url);
    } // ENGINE.log('downloadPDF4Saved() - end.');

  },
