    var valve2 = ENGINE.Simulator.searchProductAt('valve', valve2_id);
    var accessory1 = ENGINE.Simulator.searchProductAt('accessory', accessory1_id);
    var accessory2 = ENGINE.Simulator.searchProductAt('accessory', accessory2_id);
